from collections import defaultdict, deque

def solve(n, edges, src=0):
    g=defaultdict(list)
    for e in edges:
        if len(e)==2: u,v=e; g[u].append(v); g[v].append(u)
        else: u,v,w=e; g[u].append((v,w))
    # BFS distances as a common baseline — replace with Dijkstra/DFS/topo as required by "Graph Representation | C++"
    dist=[-1]*n; q=deque([src]); dist[src]=0
    while q:
        u=q.popleft()
        for item in g[u]:
            v = item[0] if isinstance(item, tuple) else item
            if dist[v]<0:
                dist[v]=dist[u]+1; q.append(v)
    return dist
